		const std::uint32_t t = s_[1] << 9;
		s_[2] ^= s_[0];
		s_[3] ^= s_[1];
		s_[1] ^= s_[2];
		s_[0] ^= s_[3];
		s_[2] ^= t;
		s_[3] = detail::RotL(s_[3], 11);
		return result;
	}

