		template <class SeedSeq,
			std::enable_if_t<detail::is_seed_sequence_v<SeedSeq>
				&& !std::is_same_v<std::decay_t<SeedSeq>, state_type>
				&& !std::is_same_v<std::decay_t<SeedSeq>, Xoshiro256StarStar>>* = nullptr>
