		/// @brief 前进 2^128 步，用于创建并行子序列
		/// @note 等价于调用 2^128 次 operator()
		/// @sa longJump(), MakeStreamEngine()
		constexpr void jump() noexcept;

		/// @brief 前进 2^192 步，用于创建更稀疏的并行子序列
		/// @note 等价于调用 2^192 次 operator()
		/// @sa jump(), MakeStreamEngine()
