//
//========================================================================================
//
//	快速上手
//
//		#include “RandX_Cpp17.hpp”
//
//		// 最简用法：直接调用便捷函数（内部使用线程局部 Xoshiro256StarStar）
//		int   dice  = RandX::RandInt(1, 6);     // [1, 6] 闭区间整数
