	/// @return 线程局部 Xoshiro256StarStar 引擎的左值引用
	/// @warning 返回引用的生命周期严格绑定于当前线程的线程局部存储（TLS），
	///          严禁跨线程转移引用、捕获引用传递给异地异步任务（如 std::async、线程池）。
	[[nodiscard]]
	inline Xoshiro256StarStar& DefaultEngine()
