		[[nodiscard]]
		inline constexpr bool HasCryptoGradeOsEntropy() noexcept
		{
#	if (defined(_WIN32) && __has_include(<bcrypt.h>)) || (defined(__linux__) && __has_include(<sys/random.h>)) || (defined(__APPLE__) && __has_include(<Security/Security.h>))
			return true;
#	else
