	/// @param max 上界（含）
	/// @return 均匀分布于 [0, max] 的随机整数
	template <std::integral T = int>
		requires (!std::same_as<std::remove_cv_t<T>, bool>)
	[[nodiscard]]
	inline T RandInt(T max)
	{
		return RandInt<T>(T{0}, max);
