	/// @brief 采用无偏 Bit-Extraction 直通算法生成 [0, 1) 半开区间的随机浮点数（默认线程引擎）
	/// @tparam T 浮点数类型（float / double）
	/// @return [0, 1) 范围内的无偏伪随机浮点数
	template <std::floating_point T = double>
	[[nodiscard]]
	inline T RandCanonical()
	{
		return RandCanonical<T>(DefaultEngine());
	}

