		template <class C>
		struct is_random_access_container<C, std::void_t<
			decltype(std::begin(std::declval<C&>())),
			decltype(std::end(std::declval<C&>())),
			decltype(std::size(std::declval<C&>()))>>
			: is_random_access_iterator<decltype(std::begin(std::declval<C&>()))> {};

