	/// @brief 用 [min, max] 范围的随机整数填充迭代器区间（指定引擎重载）
	/// @param engine 自定义随机数引擎
	/// @param first 起始迭代器
	/// @param last 结束迭代器
	/// @param min 随机数下界（含）
	/// @param max 随机数上界（含）
	template <class It, class T, class Engine,
		std::enable_if_t<detail::is_rand_fillable_v<It, T> && std::is_integral_v<T> && !std::is_same_v<std::remove_cv_t<T>, bool> && detail::is_random_engine_v<Engine>>* = nullptr>
	inline void RandFill(Engine& engine, It first, It last, T min, T max)
	{
		if (min > max)
			throw std::invalid_argument("RandFill: min > max");
		using DistType = std::conditional_t<(sizeof(T) < sizeof(short)),
			std::conditional_t<std::is_signed_v<T>, int, unsigned int>, T>;
		std::uniform_int_distribution<DistType> dist(static_cast<DistType>(min), static_cast<DistType>(max));
		for (; first != last; ++first)
			*first = static_cast<T>(dist(engine));
	}

	/// @brief 用 [min, max) 范围的随机浮点数填充迭代器区间（指定引擎重载）
	/// @param engine 自定义随机数引擎
	/// @param first 起始迭代器
	/// @param last 结束迭代器
	/// @param min 随机数下界（含）
	/// @param max 随机数上界（不含）
	template <class It, class T, class Engine,
		std::enable_if_t<detail::is_rand_fillable_v<It, T> && std::is_floating_point_v<T> && detail::is_random_engine_v<Engine>>* = nullptr>
	inline void RandFill(Engine& engine, It first, It last, T min, T max)
	{
		detail::RealIntervalKernel<T> kernel(min, max, "RandFill");
		if (kernel.IsDegenerate())
		{
			const T val = kernel.DegenerateValue();
			for (; first != last; ++first)
				*first = val;
			return;
		}
		for (; first != last; ++first)
			*first = kernel.Generate(engine);
	}

