	/// @param min 随机数下界（含）
	/// @param max 随机数上界（不含）
	template <class It, class T,
		std::enable_if_t<detail::is_rand_fillable_v<It, T> && std::is_floating_point_v<T>>* = nullptr>
	inline void RandFill(It first, It last, T min, T max)
