namespace RandX
{
	// 生成器的默认种子值
	inline constexpr std::uint64_t DefaultSeed = 1234567890ULL;

	// 将给定的 uint32 值 `i` 转换为 32 位浮点
	// 范围在 [0.0f, 1.0f) 的数值
	template <class Uint32, std::enable_if_t<std::is_same_v<Uint32, std::uint32_t>>* = nullptr>
	[[nodiscard]]
	inline constexpr float FloatFromBits(Uint32 i) noexcept;

	// 将给定的 uint64 值 `i` 转换为 64 位浮点
	// 范围在 [0.0, 1.0) 的数值
	template <class Uint64, std::enable_if_t<std::is_same_v<Uint64, std::uint64_t>>* = nullptr>
	[[nodiscard]]
	inline constexpr double DoubleFromBits(Uint64 i) noexcept;

	class SFC64;

	// ── 引擎基础设施（提前定义，供 EngineBase CRTP 基类使用） ──
	namespace detail
	{
		[[nodiscard]]
		inline constexpr std::uint64_t RotL(const std::uint64_t x, const int s) noexcept
		{
			const int count = s & 63;
			return count == 0 ? x : ((x << count) | (x >> (64 - count)));
		}

		[[nodiscard]]
		inline constexpr std::uint32_t RotL(const std::uint32_t x, const int s) noexcept
		{
			const int count = s & 31;
			return count == 0 ? x : ((x << count) | (x >> (32 - count)));
		}

		template <std::size_t N>
		[[nodiscard]]
		inline constexpr bool IsAllZero(const std::array<std::uint64_t, N>& state) noexcept
		{
			for (const auto& s : state) { if (s != 0) return false; }
			return true;
		}

		template <std::size_t N>
		[[nodiscard]]
		inline constexpr bool IsAllZero(const std::array<std::uint32_t, N>& state) noexcept
		{
			for (const auto& s : state) { if (s != 0) return false; }
			return true;
		}

		template <typename State>
		[[nodiscard]]
		inline constexpr bool IsValidState(const State& state) noexcept
		{
			return !IsAllZero(state);
		}

		template <class Engine>
		struct EngineStatePolicy
		{
			static constexpr bool AllowsZeroState = false;
		};

		template <>
		struct EngineStatePolicy<RandX::SFC64>
		{
			static constexpr bool AllowsZeroState = true;
		};

		template <class Engine, class State>
		[[nodiscard]]
		inline constexpr bool IsValidSnapshot(const State& state) noexcept
		{
			if constexpr (EngineStatePolicy<Engine>::AllowsZeroState)
			{
				return true;
			}
			else
			{
				return !IsAllZero(state);
			}
		}

		template <class S, class = void>
		struct is_seed_sequence_helper : std::false_type {};

		template <class S>
		struct is_seed_sequence_helper<S, std::void_t<
			decltype(std::declval<S&>().generate(std::declval<std::uint32_t*>(), std::declval<std::uint32_t*>()))
		>> : std::true_type {};

		template <class S>
		struct is_seed_sequence : std::integral_constant<bool,
			!std::is_integral_v<std::remove_cv_t<std::remove_reference_t<S>>> &&
			!std::is_enum_v<std::remove_cv_t<std::remove_reference_t<S>>> &&
			is_seed_sequence_helper<S>::value
		> {};

		template <class S>
		inline constexpr bool is_seed_sequence_v = is_seed_sequence<S>::value;
	}

