	/// @brief 生成随机布尔值
	/// @param p 为 true 的概率（默认 0.5）
	/// @return 以概率 p 返回 true
	[[nodiscard]]
	inline bool RandBool(double p = 0.5)
	{
		if (!std::isfinite(p) || p < 0.0 || p > 1.0)
			throw std::invalid_argument("RandBool: invalid probability p");
		std::bernoulli_distribution dist(p);
