	/// @brief 生成几何分布随机数（首次成功前的失败次数）
	/// @param p 每次成功概率（默认 0.5）
	/// @return 服从 Geometric(p) 的随机整数
	/// @throw std::overflow_error 抽样值超出返回类型范围时抛出
	template <std::integral T = int>
	[[nodiscard]]
	inline T RandGeometric(double p = 0.5)
