def selected(factor, name):
    if name.startswith('BM_ShuffleDefault'): return factor.startswith('shuffle_')
    if factor.startswith('shuffle_'): return False
    path = 'Container' if 'Container' in name else ('Iterator' if 'Iterator' in name else 'Reservoir')
    size, count = (int(part.split(':')[-1]) for part in name.rsplit('/', 2)[1:])
    engine = 'X128' if 'Xoshiro128StarStar' in name else ('X256' if 'Xoshiro256StarStar' in name else ('Mt64' if 'mt19937_64' in name else 'Default'))
    bitmap = path == 'Container' and (size, count) in ((256, 64), (1000000, 15623))
    dense = path in ('Container', 'Iterator') and (size, count) in ((256, 129), (1000000, 500001))
    reservoir = path == 'Reservoir' and (size, count) in ((256, 1), (256, 64), (1000000, 1024))
    if factor in ('distribution_flatten', 'mapping_inline'): return bitmap or reservoir
    if factor == 'bitmap_inline': return bitmap
    if factor == 'dense_bound': return dense
    if factor == 'linear_boundary': return path in ('Container', 'Iterator') and count in (1, 2) and size == 256
    if factor == 'sample_kernels': return dense or reservoir
    if factor == 'sample_adapters': return engine != 'Mt64' and (dense or (path == 'Container' and size in (0, 256) and count in (0, 1, 64)))
    return False

def prepare_control():
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    kernel.GetCurrentProcess.restype = ctypes.c_void_p
    kernel.GetProcessAffinityMask.argtypes = (ctypes.c_void_p, ctypes.POINTER(ctypes.c_size_t), ctypes.POINTER(ctypes.c_size_t))
    kernel.SetProcessAffinityMask.argtypes = (ctypes.c_void_p, ctypes.c_size_t)
    allowed, system = ctypes.c_size_t(), ctypes.c_size_t()
    if not kernel.GetProcessAffinityMask(kernel.GetCurrentProcess(), ctypes.byref(allowed), ctypes.byref(system)): raise ctypes.WinError(ctypes.get_last_error())
    mask = 1 << (allowed.value.bit_length() - 1)
    (WORK / 'control.json').write_text(json.dumps({'affinity_mask': mask, 'priority': 'ABOVE_NORMAL_PRIORITY_CLASS', 'scope': '仅实验子进程'}, ensure_ascii=False), encoding='utf-8')
    return kernel, mask

def run_controlled(args, kernel, mask):
    process = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=subprocess.ABOVE_NORMAL_PRIORITY_CLASS)
    if not kernel.SetProcessAffinityMask(ctypes.c_void_p(int(process._handle)), mask): raise ctypes.WinError(ctypes.get_last_error())
    stdout, stderr = process.communicate()
    if process.returncode: raise subprocess.CalledProcessError(process.returncode, args, stdout, stderr)
    return stdout + stderr

def measure(confirmation=False):
    kernel, mask = prepare_control()
    stage = 'confirmation' if confirmation else 'initial'
    initial = json.loads((WORK / 'initial-summary.json').read_text(encoding='utf-8')) if confirmation else None
    summary = {}
    for standard in STANDARDS:
        group = POLICY['groups'][f'sampling_cpp{standard}']
        rounds = group['confirmation_repetitions'] if confirmation else group['repetitions']
        duration = group['confirmation_min_time'] if confirmation else group['min_time']
        names = json.loads((WORK / f'cpp{standard}/reference/measurement-names.json').read_text())
        summary[str(standard)] = {}
        for factor in FACTORS:
            cases = [name for name in names if selected(factor, name)]
            if confirmation:
                previous = initial[str(standard)][factor]
                changed = {row['name'] for row in previous if abs(row['cpu']['change']) > group['tolerance']}
                representatives = {name for name in cases if ('Xoshiro256StarStar' in name or 'Default' in name)}
                cases = sorted(changed | representatives)
            filter = '^(' + '|'.join(re.escape(name).replace(r'\ ', ' ') for name in cases) + ')$'
            observations = {variant: {} for variant in ('reference', factor)}
            for index in range(rounds):
                order = ('reference', factor) if index % 2 == 0 else (factor, 'reference')
                for variant in order:
                    output = WORK / stage / f'cpp{standard}' / factor / f'{variant}-{index}.json'
                    output.parent.mkdir(parents=True, exist_ok=True)
                    args = [str(WORK / f'cpp{standard}' / variant / 'measurement.exe'), f'--benchmark_filter={filter}', f'--benchmark_min_time={duration}', '--benchmark_repetitions=1', f'--benchmark_out={output}', '--benchmark_out_format=json']
                    output.with_suffix('.log').write_bytes(run_controlled(args, kernel, mask))
                    data = json.loads(output.read_text(encoding='cp1252'))
                    output.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
                    actual = {record['name'] for record in data['benchmarks']}
                    if actual != set(cases): raise RuntimeError('case set differs')
                    for record in data['benchmarks']:
                        observations[variant].setdefault(record['name'], []).append({'cpu_ns': record['cpu_time'], 'real_ns': record['real_time']})
                print(standard, stage, factor, 'round', index + 1, 'cases', len(cases), flush=True)
            rows = []
            for name in cases:
                row = {'name': name, 'reference_rounds': observations['reference'][name], 'factor_rounds': observations[factor][name]}
                for key, metric in (('cpu', 'cpu_ns'), ('real', 'real_ns')):
                    before = statistics.median(record[metric] for record in row['reference_rounds'])
                    after = statistics.median(record[metric] for record in row['factor_rounds'])
                    row[key] = {'reference_ns': before, 'factor_ns': after, 'change': after / before - 1}
                rows.append(row)
            summary[str(standard)][factor] = rows
            (WORK / f'{stage}-summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf-8')
            print(standard, factor, 'CPU range', min(row['cpu']['change'] for row in rows), max(row['cpu']['change'] for row in rows), flush=True)
